package com.vaibhav.ediflow.order.domain;
import jakarta.persistence.*; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="dead_letter_records") public class DeadLetterRecord {
 @Id private UUID id; @Column(name="source_topic",nullable=false) private String sourceTopic; @Column(name="partner_id") private UUID partnerId; @Column(name="partner_code") private String partnerCode; @Column(name="raw_payload",columnDefinition="text") private String rawPayload; @Column(name="canonical_event",columnDefinition="text") private String canonicalEvent; @Column(name="error_reason",nullable=false,length=2000) private String errorReason; @Column(name="retry_topic",nullable=false) private String retryTopic; @Column(name="retry_count",nullable=false) private int retryCount; @Enumerated(EnumType.STRING) @Column(nullable=false) private DeadLetterStatus status; @Column(name="created_at",nullable=false) private Instant createdAt;
 protected DeadLetterRecord(){} public DeadLetterRecord(UUID id,String source,UUID partnerId,String partnerCode,String raw,String canonical,String error,String retryTopic,Instant created){this.id=id;sourceTopic=source;this.partnerId=partnerId;this.partnerCode=partnerCode;rawPayload=raw;canonicalEvent=canonical;errorReason=error;this.retryTopic=retryTopic;createdAt=created;status=DeadLetterStatus.OPEN;}
 public void retried(){retryCount++;status=DeadLetterStatus.RETRIED;} public UUID getId(){return id;} public String getSourceTopic(){return sourceTopic;} public UUID getPartnerId(){return partnerId;} public String getPartnerCode(){return partnerCode;} public String getRawPayload(){return rawPayload;} public String getCanonicalEvent(){return canonicalEvent;} public String getErrorReason(){return errorReason;} public String getRetryTopic(){return retryTopic;} public int getRetryCount(){return retryCount;} public DeadLetterStatus getStatus(){return status;} public Instant getCreatedAt(){return createdAt;}
}
